<?php
/** Cash and bank accounts, collections, payments and transfers. */
defined('ABSPATH') || exit;
final class SG_Cash_Bank {
 private static function t(string $n):string{global $wpdb;return $wpdb->prefix.'sg_'.$n;}
 public static function init():void{add_action('rest_api_init',[__CLASS__,'routes']);}
 public static function routes():void{
  register_rest_route('sg/v1','/cash-accounts',[
   ['methods'=>WP_REST_Server::READABLE,'callback'=>[__CLASS__,'list_accounts'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('cash.view')],
   ['methods'=>WP_REST_Server::CREATABLE,'callback'=>[__CLASS__,'create_account'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('cash.create')]
  ]);
  register_rest_route('sg/v1','/cash-parties',['methods'=>WP_REST_Server::READABLE,'callback'=>[__CLASS__,'parties'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('cash.create')]);
  register_rest_route('sg/v1','/cash-accounts/(?P<id>\d+)/transactions',[
   ['methods'=>WP_REST_Server::READABLE,'callback'=>[__CLASS__,'transactions'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('cash.view')],
   ['methods'=>WP_REST_Server::CREATABLE,'callback'=>[__CLASS__,'post_transaction'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('cash.create')]
  ]);
  register_rest_route('sg/v1','/cash-transfers',['methods'=>WP_REST_Server::CREATABLE,'callback'=>[__CLASS__,'transfer'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('cash.transfer')]);
 }
 private static function valid_date(string $d):bool{$x=DateTime::createFromFormat('!Y-m-d',$d);return $x&&$x->format('Y-m-d')===$d;}
 private static function amount($v):string|false{$v=trim((string)$v);if(!preg_match('/^[0-9]{1,14}(\.[0-9]{1,2})?$/',$v)||(float)$v<=0)return false;$p=explode('.',$v,2);return(ltrim($p[0],'0')?:'0').'.'.str_pad($p[1]??'',2,'0');}
 private static function ledger(string $code,string $name,string $class):int|WP_Error{global $wpdb;$t=self::t('ledger_accounts');$id=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$t} WHERE account_code=%s",$code));if($id)return$id;$n=current_time('mysql',true);if(false===$wpdb->insert($t,['account_code'=>$code,'account_name'=>$name,'account_class'=>$class,'is_system'=>1,'is_active'=>1,'created_at'=>$n,'updated_at'=>$n]))return new WP_Error('sg_ledger','Muhasebe hesabı oluşturulamadı.');return(int)$wpdb->insert_id;}
 private static function journal(string $type,string $date,string $desc,string $doc,array $lines,string $key):int|WP_Error{global $wpdb;$now=current_time('mysql',true);$no='KB-'.wp_date('Ymd').'-'.strtoupper(wp_generate_password(8,false,false));if(false===$wpdb->insert(self::t('journal_entries'),['entry_no'=>$no,'entry_date'=>$date,'entry_type'=>$type,'source_module'=>'cash_bank','source_key'=>$key,'document_no'=>$doc,'description'=>$desc,'status'=>'posted','created_by'=>get_current_user_id(),'posted_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now,'posted_at'=>$now]))return new WP_Error('sg_journal','Muhasebe fişi oluşturulamadı.');$id=(int)$wpdb->insert_id;$d=0;$c=0;$i=1;foreach($lines as $line){$line=array_merge(['entry_id'=>$id,'line_no'=>$i++,'party_account_id'=>null,'cash_account_id'=>null,'description'=>$desc,'created_at'=>$now],$line);$d+=(float)$line['debit'];$c+=(float)$line['credit'];if(false===$wpdb->insert(self::t('journal_lines'),$line))return new WP_Error('sg_journal_line','Muhasebe fiş satırı kaydedilemedi.');}if(abs($d-$c)>.001)return new WP_Error('sg_unbalanced','Muhasebe fişi dengeli değil.');return$id;}
 public static function parties():WP_REST_Response{global $wpdb;$rows=$wpdb->get_results("SELECT p.id AS party_id,p.party_type,p.party_code,p.company_name FROM ".self::t('parties')." p INNER JOIN ".self::t('accounts')." a ON a.party_id=p.id AND a.status='active' WHERE p.status='active' ORDER BY p.company_name",ARRAY_A);return new WP_REST_Response(['items'=>$rows?:[]],200);}
 public static function list_accounts():WP_REST_Response{global $wpdb;$rows=$wpdb->get_results("SELECT c.id,c.account_code,c.account_name,c.account_kind,c.bank_name,c.iban,c.currency,COALESCE(SUM(CASE WHEN je.status='posted' THEN jl.debit-jl.credit ELSE 0 END),0) balance FROM ".self::t('cash_accounts')." c LEFT JOIN ".self::t('journal_lines')." jl ON jl.cash_account_id=c.id LEFT JOIN ".self::t('journal_entries')." je ON je.id=jl.entry_id WHERE c.status='active' GROUP BY c.id ORDER BY c.account_kind,c.account_name",ARRAY_A);foreach($rows?:[] as &$r)$r['balance']=number_format((float)$r['balance'],2,'.','');return new WP_REST_Response(['items'=>$rows?:[]],200);}
 public static function create_account(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$name=sanitize_text_field((string)$r['account_name']);$kind=sanitize_key((string)$r['account_kind']);$bank=sanitize_text_field((string)$r['bank_name']);$iban=strtoupper(preg_replace('/\s+/','',(string)$r['iban']));$date=sanitize_text_field((string)$r['opening_date']);$raw=(string)($r['opening_balance']??'');$opening=$raw===''?null:self::amount($raw);$key=sanitize_text_field((string)$r->get_header('Idempotency-Key'));if(strlen($key)<16||strlen($key)>100)return new WP_Error('sg_cash_key','Tekrarlı kayıt koruması için işlem anahtarı gerekli.',['status'=>400]);if($name===''||!in_array($kind,['cash','bank'],true))return new WP_Error('sg_cash_fields','Hesap adı ve türü zorunludur.', ['status'=>400]);if($raw!==''&&(!$opening||!self::valid_date($date)))return new WP_Error('sg_cash_opening','Açılış tutarı veya tarihi geçersiz.',['status'=>400]);if($kind==='bank'&&$iban!==''&&!preg_match('/^TR[0-9A-Z]{24}$/',$iban))return new WP_Error('sg_cash_iban','IBAN TR ile başlayan 26 karakter olmalıdır.',['status'=>400]);$hash=hash('sha256',wp_json_encode([$name,$kind,$bank,$iban,$date,$opening]));$idem=self::t('idempotency_keys');$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$idem} WHERE idempotency_key=%s",$key),ARRAY_A);if($old){if((int)$old['user_id']!==get_current_user_id()||!hash_equals($old['payload_hash'],$hash))return new WP_Error('sg_cash_key_conflict','İşlem anahtarı farklı bir kayıt için kullanılmış.',['status'=>409]);if($old['status']==='completed')return new WP_REST_Response(['message'=>'Hesap daha önce oluşturuldu.','id'=>(int)$old['result_reference'],'duplicate'=>true],200);return new WP_Error('sg_cash_busy','Hesap oluşturma işlemi kontrol ediliyor.',['status'=>409]);}$wpdb->query('START TRANSACTION');try{$now=current_time('mysql',true);if(false===$wpdb->insert($idem,['idempotency_key'=>$key,'operation'=>'cash.account.create','user_id'=>get_current_user_id(),'payload_hash'=>$hash,'status'=>'processing','created_at'=>$now]))throw new RuntimeException('İşlem koruması kaydedilemedi.');$iid=(int)$wpdb->insert_id;$seq=(int)$wpdb->get_var('SELECT COUNT(*) FROM '.self::t('cash_accounts'))+1;$code=($kind==='cash'?'KS-':'BN-').str_pad((string)$seq,6,'0',STR_PAD_LEFT);$ledger=self::ledger('CB-'.str_pad((string)$seq,6,'0',STR_PAD_LEFT),$name,'asset');if(is_wp_error($ledger))throw new RuntimeException($ledger->get_error_message());$now=current_time('mysql',true);if(false===$wpdb->insert(self::t('cash_accounts'),['account_code'=>$code,'account_name'=>$name,'account_kind'=>$kind,'bank_name'=>$bank,'iban'=>$iban,'currency'=>'TRY','ledger_account_id'=>$ledger,'opening_date'=>$date?:null,'status'=>'active','created_by'=>get_current_user_id(),'updated_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now]))throw new RuntimeException('Hesap kaydedilemedi.');$id=(int)$wpdb->insert_id;if($opening!==null){$counter=self::ledger('399999','Açılış ve düzeltme karşılığı','equity');if(is_wp_error($counter))throw new RuntimeException($counter->get_error_message());$entry=self::journal('cash_opening',$date,'Kasa/banka açılış bakiyesi','',[['ledger_account_id'=>$ledger,'cash_account_id'=>$id,'debit'=>$opening,'credit'=>'0.00'],['ledger_account_id'=>$counter,'debit'=>'0.00','credit'=>$opening]],'cash-opening:'.$id);if(is_wp_error($entry))throw new RuntimeException($entry->get_error_message());if(false===$wpdb->insert(self::t('cash_transactions'),['journal_entry_id'=>$entry,'cash_account_id'=>$id,'transaction_date'=>$date,'direction'=>'in','amount'=>$opening,'description'=>'Açılış bakiyesi','created_by'=>get_current_user_id(),'created_at'=>$now]))throw new RuntimeException('Açılış hareketi kaydedilemedi.');}$wpdb->update($idem,['result_reference'=>(string)$id,'status'=>'completed','completed_at'=>$now],['id'=>$iid]);$wpdb->insert(self::t('audit_logs'),['user_id'=>get_current_user_id(),'event_key'=>'cash.account_created','object_type'=>'cash_account','object_id'=>$id,'request_id'=>$key,'details'=>wp_json_encode(['account_code'=>$code,'opening_balance'=>$opening]),'created_at'=>$now]);$wpdb->query('COMMIT');return new WP_REST_Response(['message'=>'Kasa/banka hesabı oluşturuldu.','id'=>$id],201);}catch(Throwable $e){$wpdb->query('ROLLBACK');return new WP_Error('sg_cash_create',$e->getMessage(),['status'=>500]);}}
 public static function transactions(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$id=absint($r['id']);$a=$wpdb->get_row($wpdb->prepare("SELECT id,account_name,account_kind FROM ".self::t('cash_accounts')." WHERE id=%d AND status='active'",$id),ARRAY_A);if(!$a)return new WP_Error('sg_cash_missing','Kasa/banka hesabı bulunamadı.',['status'=>404]);$rows=$wpdb->get_results($wpdb->prepare("SELECT t.id,t.transaction_date,t.direction,t.amount,t.document_no,t.description,je.entry_no,je.entry_type,p.company_name FROM ".self::t('cash_transactions')." t JOIN ".self::t('journal_entries')." je ON je.id=t.journal_entry_id LEFT JOIN ".self::t('journal_lines')." jl ON jl.entry_id=je.id AND jl.party_account_id IS NOT NULL LEFT JOIN ".self::t('accounts')." ca ON ca.id=jl.party_account_id LEFT JOIN ".self::t('parties')." p ON p.id=ca.party_id WHERE t.cash_account_id=%d AND je.status='posted' ORDER BY t.transaction_date DESC,t.id DESC LIMIT 500",$id),ARRAY_A);return new WP_REST_Response(['account'=>$a,'items'=>$rows?:[]],200);}
 public static function post_transaction(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$cid=absint($r['id']);$type=sanitize_key((string)$r['transaction_type']);$amount=self::amount($r['amount']??'');$date=sanitize_text_field((string)$r['transaction_date']);$pid=absint($r['party_id']??0);$doc=sanitize_text_field((string)$r['document_no']);$desc=sanitize_textarea_field((string)$r['description']);$key=sanitize_text_field((string)$r->get_header('Idempotency-Key'));if(!$amount||!self::valid_date($date)||!in_array($type,['collection','payment','cash_in','cash_out'],true)||strlen($key)<16||strlen($key)>100)return new WP_Error('sg_cash_input','İşlem bilgilerini kontrol edin.',['status'=>400]);$cash=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('cash_accounts')." WHERE id=%d AND status='active'",$cid),ARRAY_A);if(!$cash)return new WP_Error('sg_cash_missing','Aktif kasa/banka hesabı bulunamadı.',['status'=>404]);$pa=0;$pl=0;if(in_array($type,['collection','payment'],true)){$party=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('parties')." WHERE id=%d AND status='active'",$pid),ARRAY_A);if(!$party||($type==='collection'&&$party['party_type']!=='customer')||($type==='payment'&&$party['party_type']!=='supplier'))return new WP_Error('sg_cash_party','Tahsilatta müşteri, ödemede tedarikçi seçin.',['status'=>400]);$acct=$wpdb->get_row($wpdb->prepare("SELECT id FROM ".self::t('accounts')." WHERE party_id=%d AND account_type=%s",$pid,$type==='collection'?'receivable':'payable'),ARRAY_A);if(!$acct)return new WP_Error('sg_cash_party_account','Önce cari hesap için açılış veya borç/alacak hareketi oluşturun.',['status'=>400]);$pa=(int)$acct['id'];$pl=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM ".self::t('ledger_accounts')." WHERE account_code=%s",'PA-'.str_pad((string)$pid,8,'0',STR_PAD_LEFT)));if(!$pl)return new WP_Error('sg_cash_party_ledger','Cari muhasebe hesabı bulunamadı.',['status'=>400]);}$hash=hash('sha256',wp_json_encode([$cid,$type,$amount,$date,$pid,$doc,$desc]));$idem=self::t('idempotency_keys');$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$idem} WHERE idempotency_key=%s",$key),ARRAY_A);if($old){if((int)$old['user_id']!==get_current_user_id()||!hash_equals($old['payload_hash'],$hash))return new WP_Error('sg_cash_key_conflict','İşlem anahtarı farklı bir kayıt için kullanılmış.',['status'=>409]);if($old['status']==='completed')return new WP_REST_Response(['message'=>'İşlem daha önce kaydedildi.','duplicate'=>true],200);return new WP_Error('sg_cash_busy','İşlem kontrol ediliyor.',['status'=>409]);}$wpdb->query('START TRANSACTION');try{$now=current_time('mysql',true);if(false===$wpdb->insert($idem,['idempotency_key'=>$key,'operation'=>'cash.transaction','user_id'=>get_current_user_id(),'payload_hash'=>$hash,'status'=>'processing','created_at'=>$now]))throw new RuntimeException('Tekrarlı kayıt koruması oluşturulamadı.');$iid=(int)$wpdb->insert_id;$cl=(int)$cash['ledger_account_id'];if($type==='collection'){$lines=[['ledger_account_id'=>$cl,'cash_account_id'=>$cid,'debit'=>$amount,'credit'=>'0.00'],['ledger_account_id'=>$pl,'party_account_id'=>$pa,'debit'=>'0.00','credit'=>$amount]];$dir='in';$et='collection';}elseif($type==='payment'){$lines=[['ledger_account_id'=>$pl,'party_account_id'=>$pa,'debit'=>$amount,'credit'=>'0.00'],['ledger_account_id'=>$cl,'cash_account_id'=>$cid,'debit'=>'0.00','credit'=>$amount]];$dir='out';$et='payment';}elseif($type==='cash_in'){$l=self::ledger('600001','Diğer gelirler','income');if(is_wp_error($l))throw new RuntimeException($l->get_error_message());$lines=[['ledger_account_id'=>$cl,'cash_account_id'=>$cid,'debit'=>$amount,'credit'=>'0.00'],['ledger_account_id'=>$l,'debit'=>'0.00','credit'=>$amount]];$dir='in';$et='cash_income';}else{$l=self::ledger('700001','Diğer giderler','expense');if(is_wp_error($l))throw new RuntimeException($l->get_error_message());$lines=[['ledger_account_id'=>$l,'debit'=>$amount,'credit'=>'0.00'],['ledger_account_id'=>$cl,'cash_account_id'=>$cid,'debit'=>'0.00','credit'=>$amount]];$dir='out';$et='cash_expense';}$entry=self::journal($et,$date,$desc,$doc,$lines,'cash-tx:'.hash('sha256',$key));if(is_wp_error($entry))throw new RuntimeException($entry->get_error_message());if(false===$wpdb->insert(self::t('cash_transactions'),['journal_entry_id'=>$entry,'cash_account_id'=>$cid,'transaction_date'=>$date,'direction'=>$dir,'amount'=>$amount,'document_no'=>$doc,'description'=>$desc,'created_by'=>get_current_user_id(),'created_at'=>$now]))throw new RuntimeException('Kasa/banka hareketi kaydedilemedi.');$wpdb->update($idem,['result_reference'=>(string)$entry,'status'=>'completed','completed_at'=>$now],['id'=>$iid]);$wpdb->insert(self::t('audit_logs'),['user_id'=>get_current_user_id(),'event_key'=>'cash.transaction_posted','object_type'=>'cash_account','object_id'=>$cid,'request_id'=>$key,'details'=>wp_json_encode(['entry_id'=>$entry,'type'=>$type,'amount'=>$amount,'party_id'=>$pid]),'created_at'=>$now]);$wpdb->query('COMMIT');return new WP_REST_Response(['message'=>'Kasa/banka hareketi kaydedildi.','entry_id'=>$entry],201);}catch(Throwable $e){$wpdb->query('ROLLBACK');return new WP_Error('sg_cash_post',$e->getMessage(),['status'=>500]);}}
 public static function transfer(WP_REST_Request $r):WP_REST_Response|WP_Error{global $wpdb;$from=absint($r['from_account_id']);$to=absint($r['to_account_id']);$amount=self::amount($r['amount']??'');$date=sanitize_text_field((string)$r['transaction_date']);$desc=sanitize_textarea_field((string)$r['description']);$doc=sanitize_text_field((string)$r['document_no']);$key=sanitize_text_field((string)$r->get_header('Idempotency-Key'));if(!$amount||$from===$to||!self::valid_date($date)||strlen($key)<16||strlen($key)>100)return new WP_Error('sg_transfer_input','Transfer bilgilerini kontrol edin.',['status'=>400]);$a=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('cash_accounts')." WHERE id=%d AND status='active'",$from),ARRAY_A);$b=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::t('cash_accounts')." WHERE id=%d AND status='active'",$to),ARRAY_A);if(!$a||!$b)return new WP_Error('sg_transfer_accounts','Kaynak ve hedef hesap aktif olmalıdır.',['status'=>400]);$hash=hash('sha256',wp_json_encode([$from,$to,$amount,$date,$desc,$doc]));$idem=self::t('idempotency_keys');$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$idem} WHERE idempotency_key=%s",$key),ARRAY_A);if($old){if((int)$old['user_id']!==get_current_user_id()||!hash_equals($old['payload_hash'],$hash))return new WP_Error('sg_transfer_conflict','İşlem anahtarı çakışması.',['status'=>409]);if($old['status']==='completed')return new WP_REST_Response(['message'=>'Transfer daha önce kaydedildi.','duplicate'=>true],200);return new WP_Error('sg_transfer_busy','Transfer kontrol ediliyor.',['status'=>409]);}$wpdb->query('START TRANSACTION');try{$now=current_time('mysql',true);if(false===$wpdb->insert($idem,['idempotency_key'=>$key,'operation'=>'cash.transfer','user_id'=>get_current_user_id(),'payload_hash'=>$hash,'status'=>'processing','created_at'=>$now]))throw new RuntimeException('Transfer koruması oluşturulamadı.');$iid=(int)$wpdb->insert_id;$entry=self::journal('cash_transfer',$date,$desc,$doc,[['ledger_account_id'=>(int)$b['ledger_account_id'],'cash_account_id'=>$to,'debit'=>$amount,'credit'=>'0.00'],['ledger_account_id'=>(int)$a['ledger_account_id'],'cash_account_id'=>$from,'debit'=>'0.00','credit'=>$amount]],'cash-transfer:'.hash('sha256',$key));if(is_wp_error($entry))throw new RuntimeException($entry->get_error_message());$group=wp_generate_uuid4();foreach([[$from,'out'],[$to,'in']] as $v){if(false===$wpdb->insert(self::t('cash_transactions'),['journal_entry_id'=>$entry,'cash_account_id'=>$v[0],'transaction_date'=>$date,'direction'=>$v[1],'amount'=>$amount,'document_no'=>$doc,'transfer_group'=>$group,'description'=>$desc,'created_by'=>get_current_user_id(),'created_at'=>$now]))throw new RuntimeException('Transfer hareketi kaydedilemedi.');}$wpdb->update($idem,['result_reference'=>(string)$entry,'status'=>'completed','completed_at'=>$now],['id'=>$iid]);$wpdb->insert(self::t('audit_logs'),['user_id'=>get_current_user_id(),'event_key'=>'cash.transfer_posted','object_type'=>'cash_account','object_id'=>$from,'request_id'=>$key,'details'=>wp_json_encode(['entry_id'=>$entry,'from'=>$from,'to'=>$to,'amount'=>$amount]),'created_at'=>$now]);$wpdb->query('COMMIT');return new WP_REST_Response(['message'=>'Hesaplar arası transfer kaydedildi.','entry_id'=>$entry],201);}catch(Throwable $e){$wpdb->query('ROLLBACK');return new WP_Error('sg_transfer_failed',$e->getMessage(),['status'=>500]);}}
}
